# 文件路径：scripts/check_python.py
import subprocess
import sys
import json
import os

def ensure_tools():
    """确保检查工具已安装"""
    for pkg in ["flake8", "radon"]:
        try:
            __import__(pkg.replace("-", "_"))
        except ImportError:
            subprocess.run([sys.executable, "-m", "pip", "install", pkg,
                            "--break-system-packages", "--quiet"])

def check_syntax(file_path: str) -> dict:
    """检查 Python 语法"""
    result = subprocess.run(
        [sys.executable, "-m", "py_compile", file_path],
        capture_output=True, text=True
    )
    if result.returncode == 0:
        return {"passed": True, "errors": []}
    return {
        "passed": False,
        "errors": [result.stderr.strip()]
    }

def check_style(file_path: str) -> list:
    """运行 flake8 检查代码风格，返回问题列表"""
    result = subprocess.run(
        ["python", "-m", "flake8", file_path,
         "--max-line-length=100",
         "--format=%(row)d:%(col)d %(code)s %(text)s"],
        capture_output=True, text=True
    )
    issues = []
    for line in result.stdout.strip().splitlines():
        parts = line.split(" ", 2)
        if len(parts) >= 3:
            loc, code, text = parts
            row, col = loc.split(":")
            issues.append({
                "line": int(row), "col": int(col),
                "code": code,     "message": text
            })
    return issues

def check_complexity(file_path: str) -> list:
    """用 radon 分析函数复杂度，返回复杂度高的函数"""
    result = subprocess.run(
        ["python", "-m", "radon", "cc", file_path, "-s", "--json"],
        capture_output=True, text=True
    )
    try:
        data      = json.loads(result.stdout)
        functions = data.get(file_path, [])
        # 只返回复杂度等级 C 以上（复杂度 > 10）的函数
        return [
            {"name": f["name"], "complexity": f["complexity"],
             "rank": f["rank"], "line": f["lineno"]}
            for f in functions
            if f.get("rank", "A") in ("C", "D", "E", "F")
        ]
    except Exception:
        return []

def review_python(file_path: str) -> dict:
    """执行完整的 Python 代码审查"""
    if not os.path.exists(file_path):
        return {"status": "error", "message": f"文件不存在：{file_path}"}

    ensure_tools()

    syntax     = check_syntax(file_path)
    style      = check_style(file_path) if syntax["passed"] else []
    complexity = check_complexity(file_path) if syntax["passed"] else []

    # 计算总体评级
    error_count   = len([i for i in style if i["code"].startswith("E")])
    warning_count = len([i for i in style if i["code"].startswith("W")])

    if not syntax["passed"]:
        grade = "F"
    elif error_count > 10:
        grade = "C"
    elif error_count > 3:
        grade = "B"
    else:
        grade = "A"

    return {
        "status":          "success",
        "file":            os.path.basename(file_path),
        "grade":           grade,
        "syntax_ok":       syntax["passed"],
        "syntax_errors":   syntax["errors"],
        "style_issues":    style[:20],          # 最多展示 20 条
        "style_count":     len(style),
        "error_count":     error_count,
        "warning_count":   warning_count,
        "complex_functions": complexity
    }

if __name__ == "__main__":
    result = review_python(sys.argv[1] if len(sys.argv) > 1 else "")
    print(json.dumps(result, ensure_ascii=False, indent=2))

# 文件路径：scripts/load_data.py
import pandas as pd
import sys, json, os

def load(file_path: str) -> dict:
    """加载 CSV 或 Excel 文件，返回基本信息"""
    if not os.path.exists(file_path):
        return {"status": "error", "message": f"文件不存在：{file_path}"}

    ext = os.path.splitext(file_path)[1].lower()
    try:
        if ext == ".csv":
            df = pd.read_csv(file_path, encoding="utf-8")
        elif ext in (".xlsx", ".xls"):
            df = pd.read_excel(file_path)
        else:
            return {"status": "error",
                    "message": f"不支持的格式：{ext}，请使用 .csv 或 .xlsx"}
    except UnicodeDecodeError:
        # 尝试 GBK 编码（常见于中文 Windows 导出的 CSV）
        df = pd.read_csv(file_path, encoding="gbk")

    # 将 df 保存到临时文件供后续步骤使用
    tmp_path = "/home/claude/loaded_data.csv"
    df.to_csv(tmp_path, index=False, encoding="utf-8")

    return {
        "status":   "success",
        "rows":     len(df),
        "cols":     len(df.columns),
        "columns":  list(df.columns),
        "dtypes":   df.dtypes.astype(str).to_dict(),
        "tmp_path": tmp_path
    }

if __name__ == "__main__":
    print(json.dumps(load(sys.argv[1] if len(sys.argv) > 1 else ""),
                     ensure_ascii=False, indent=2))

# 文件路径：scripts/orchestrator.py
# 多 Skill 协作的编排入口脚本

import subprocess
import sys
import json
import os
import shutil

SKILLS_BASE  = "/mnt/skills/public"
WORK_DIR     = "/home/claude/report_work"
OUTPUT_DIR   = "/mnt/user-data/outputs"

def run(script_path: str, *args) -> dict:
    """运行指定脚本，返回 JSON 结果"""
    cmd    = [sys.executable, script_path] + list(args)
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    try:
        return json.loads(result.stdout)
    except json.JSONDecodeError:
        return {
            "status":  "error",
            "message": result.stderr or result.stdout or "脚本无输出"
        }

def orchestrate(input_file: str) -> dict:
    """执行完整的报告生成工作流"""
    os.makedirs(WORK_DIR, exist_ok=True)

    # ── 阶段一：数据清洗 ─────────────────────────────────
    print("【1/3】正在清洗数据...", flush=True)
    clean_result = run(
        f"{SKILLS_BASE}/data-cleaner/scripts/clean_data.py",
        input_file,
        os.path.join(WORK_DIR, "cleaned.csv")
    )
    if clean_result.get("status") != "success":
        return {"status": "error", "stage": "数据清洗",
                "message": clean_result.get("message")}

    print(f"  已清洗：删除重复行 {clean_result.get('dup_removed', 0)} 条，"
          f"填充空值 {clean_result.get('nulls_filled', 0)} 处", flush=True)

    # ── 阶段二：统计分析 ─────────────────────────────────
    print("【2/3】正在生成统计报告...", flush=True)
    stats_result = run(
        f"{SKILLS_BASE}/data-cleaner/scripts/calc_stats.py",
        clean_result["output"],
        os.path.join(WORK_DIR, "stats.json")
    )
    if stats_result.get("status") != "success":
        return {"status": "error", "stage": "统计分析",
                "message": stats_result.get("message")}

    # ── 阶段三：生成 Excel 报告 ──────────────────────────
    print("【3/3】正在生成 Excel 报告...", flush=True)
    output_name  = os.path.splitext(os.path.basename(input_file))[0] + "_report.xlsx"
    output_path  = os.path.join(OUTPUT_DIR, output_name)

    report_result = run(
        f"{SKILLS_BASE}/data-cleaner/scripts/gen_report.py",
        clean_result["output"],
        stats_result.get("output", ""),
        output_path
    )
    if report_result.get("status") != "success":
        return {"status": "error", "stage": "报告生成",
                "message": report_result.get("message")}

    # 清理工作目录
    shutil.rmtree(WORK_DIR, ignore_errors=True)

    return {
        "status":     "success",
        "output":     output_path,
        "clean_stats": {
            "dup_removed":  clean_result.get("dup_removed", 0),
            "nulls_filled": clean_result.get("nulls_filled", 0)
        }
    }

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print(json.dumps({"status": "error", "message": "用法：python orchestrator.py <文件路径>"}))
        sys.exit(1)

    result = orchestrate(sys.argv[1])
    print(json.dumps(result, ensure_ascii=False, indent=2))

# 文件路径：scripts/safe_path.py
import os

# 允许读取的目录
ALLOWED_READ_DIRS = [
    "/mnt/user-data/uploads",
    "/mnt/skills/public",
]

# 允许写入的目录
ALLOWED_WRITE_DIRS = [
    "/mnt/user-data/outputs",
    "/home/claude",
]

def is_safe_path(path: str, allowed_dirs: list) -> bool:
    """
    检查路径是否在允许的目录范围内

    防止 ../../../etc/passwd 类型的路径穿越攻击
    """
    # 解析为绝对路径（消除 .. 和符号链接）
    real_path = os.path.realpath(os.path.abspath(path))

    for allowed in allowed_dirs:
        real_allowed = os.path.realpath(allowed)
        # 检查 real_path 是否以 allowed 目录开头
        if real_path.startswith(real_allowed + os.sep) or real_path == real_allowed:
            return True
    return False

def safe_read_path(user_input: str) -> str:
    """验证读取路径，不合法时抛出异常"""
    if not is_safe_path(user_input, ALLOWED_READ_DIRS):
        raise PermissionError(
            f"拒绝访问：{user_input}\n"
            f"只允许读取以下目录：{ALLOWED_READ_DIRS}"
        )
    return os.path.realpath(user_input)

def safe_write_path(user_input: str) -> str:
    """验证写入路径，不合法时抛出异常"""
    if not is_safe_path(user_input, ALLOWED_WRITE_DIRS):
        raise PermissionError(
            f"拒绝写入：{user_input}\n"
            f"只允许写入以下目录：{ALLOWED_WRITE_DIRS}"
        )
    return os.path.realpath(user_input)

# 使用示例
if __name__ == "__main__":
    # 正常路径：通过
    ok_path = safe_read_path("/mnt/user-data/uploads/runoob.csv")
    print(f"通过：{ok_path}")

    # 穿越路径：拒绝
    try:
        bad_path = safe_read_path("/mnt/user-data/uploads/../../etc/passwd")
    except PermissionError as e:
        print(f"已拦截：{e}")
